<script setup lang="ts">
import type { TaskCard } from '~/types/task';
const route = useRoute(); const platform = usePlatformApi(); const { role, setRole } = useRole(); const id = String(route.params.id);
const { data: task, pending, error: loadError, refresh: reload } = await useAsyncData(`task-${id}`, () => platform.getTask(id)); const refresh = () => reload();
const form = reactive<TaskCard>({ title:'', topic:'', context:'', need:'', users:'', data:'', constraints:'', expectedResult:'', successCriteria:'', contact:'', interactionFormat:'' });
watch(task, value => { if (value) Object.assign(form, value.card); }, { immediate: true });
const saving = ref(false); const action = ref(''); const message = ref(''); const actionError = ref('');
const fields = [{key:'topic',label:'Тема',icon:'compass'},{key:'context',label:'Контекст',icon:'building'},{key:'need',label:'Потребность',icon:'target'},{key:'users',label:'Пользователи',icon:'users'},{key:'data',label:'Данные и материалы',icon:'file'},{key:'constraints',label:'Ограничения',icon:'shield'},{key:'expectedResult',label:'Ожидаемый результат',icon:'sparkles'},{key:'successCriteria',label:'Критерии успеха',icon:'check'},{key:'contact',label:'Контакт',icon:'message'},{key:'interactionFormat',label:'Формат взаимодействия',icon:'clock'}] as const;
async function save() { saving.value=true; action.value='save'; actionError.value=''; message.value=''; try { task.value = await platform.updateTask(id, Object.fromEntries(Object.entries(form).map(([key,value]) => [key,value.trim()])) as unknown as TaskCard); message.value='Изменения сохранены'; } catch(cause) { actionError.value=cause instanceof Error?cause.message:'Ошибка сохранения'; } finally { saving.value=false; action.value=''; } }
async function confirm() { await save(); if (actionError.value) return; saving.value=true; action.value='confirm'; try { task.value=await platform.confirmTask(id); message.value='Карточка подтверждена'; } catch(cause) { actionError.value=cause instanceof Error?cause.message:'Ошибка подтверждения'; } finally { saving.value=false; action.value=''; } }
async function publish() { action.value='publish'; if (task.value?.status==='draft') await confirm(); if (actionError.value) return; saving.value=true; action.value='publish'; try { task.value=await platform.publishTask(id); await navigateTo(`/catalog/${id}`); } catch(cause) { actionError.value=cause instanceof Error?cause.message:'Ошибка публикации'; } finally { saving.value=false; action.value=''; } }
useHead({ title:'Карточка задачи — Мост' });
</script>
<template><div class="page"><NuxtLink to="/tasks" class="back-link"><AppIcon name="back" :size="15" />К моим задачам</NuxtLink><div v-if="pending" class="state-panel" role="status"><span class="state-icon"><AppIcon name="edit" /></span><div><strong>Загружаем карточку</strong><p>Подготавливаем поля и оценку готовности.</p></div></div><div v-else-if="loadError" class="state-panel state-error" role="alert"><span class="state-icon"><AppIcon name="info" /></span><div><strong>Не удалось загрузить задачу</strong><button class="text-link" @click="refresh">Попробовать снова</button></div></div><template v-else-if="task && role==='business'"><div class="page-heading"><div><span class="eyebrow"><AppIcon name="edit" :size="14" />КАРТОЧКА ЗАДАЧИ</span><h1>Редактор карточки<span class="heading-dot">.</span></h1><p>Уточните детали, чтобы командам было проще предложить реалистичное решение.</p></div><span class="badge badge-blue">{{ taskStatusLabel(task.status) }}</span></div><form class="form-layout editor-layout" @submit.prevent="publish"><div class="panel editor-panel"><div class="panel-title"><h2><AppIcon name="file" />Содержание задачи</h2><span>Поля можно дополнять в любое время</span></div><label class="field"><span>Название <span class="required">*</span></span><input v-model="form.title" required></label><label v-for="field in fields" :key="field.key" class="field"><span><AppIcon :name="field.icon" :size="15" />{{ field.label }}<small v-if="!form[field.key]" class="missing-label">Не заполнено</small></span><textarea v-model="form[field.key]" rows="3" /></label></div><aside class="editor-sidebar"><div class="panel score-panel"><span class="eyebrow">ГОТОВНОСТЬ К ПУБЛИКАЦИИ</span><ReadinessScore :score="task.score" /><div v-if="task.breakdown.length" class="score-breakdown"><div v-for="item in task.breakdown" :key="item.name" :class="{ filled: item.points > 0 }"><span><span class="breakdown-check"><AppIcon :name="item.points > 0 ? 'check' : 'close'" :size="11" /></span>{{ breakdownLabel(item.name) }}</span><strong>{{ item.points }}<small>/{{ item.maxPoints }}</small></strong></div></div><section v-if="task.missingInformation.length" class="insight-panel missing-panel"><h3><AppIcon name="info" :size="16" />Не хватает информации</h3><ul><li v-for="item in task.missingInformation" :key="item">{{ missingFieldLabel(item) }}</li></ul></section><section v-if="task.suggestions.length" class="insight-panel suggestion-panel"><h3><AppIcon name="sparkles" :size="16" />Как улучшить</h3><ul><li v-for="item in task.suggestions" :key="item">{{ item }}</li></ul></section></div><div class="panel publish-panel"><h3>Действия с карточкой</h3><button type="button" class="button button-outline button-full" :disabled="saving" @click="save"><AppIcon name="edit" :size="15" />{{ action==='save' ? 'Сохраняем…' : 'Сохранить изменения' }}</button><button v-if="task.status==='draft'" type="button" class="button button-outline button-full" :disabled="saving" @click="confirm"><AppIcon name="check" :size="15" />{{ action==='confirm' ? 'Подтверждаем…' : 'Подтвердить карточку' }}</button><button v-if="task.status!=='published'" class="button button-primary button-full" :disabled="saving"><AppIcon name="arrowUp" :size="15" />{{ action==='publish' ? 'Публикуем…' : 'Опубликовать задачу' }}</button><p v-if="message" class="success-inline" role="status"><AppIcon name="check" :size="14" />{{ message }}</p><p v-if="actionError" class="error-text" role="alert">{{ actionError }}</p></div></aside></form></template><EmptyState v-else-if="role!=='business'" title="Редактор доступен бизнесу" description="Переключитесь в роль бизнеса, чтобы изменить карточку."><button class="button button-primary" @click="setRole('business')">Перейти в роль бизнеса</button></EmptyState><EmptyState v-else title="Задача не найдена" description="Проверьте ссылку или вернитесь к списку задач." /></div></template>
